/// <summary>
/// Update additional field information on post load
/// </summary>
/// <param name = "_staging">Entity name</param>
private void updateAdditionalData(METStocktakeVarianceDetails _staging)
{
    #Define.SalesUnitEA('EA')
    #Define.SalesUnitKG('KG')
    #Define.SalesUnitCS('CS')

    InventTable inventTable = InventTable::find(_staging.ItemId);
    UnitOfMeasureConversion     unitOfMeasureConversion;
    METExciseSiteDutySetup      siteDutySetup;
    InventItemPrices            itemPrice;
    InventDim                   itemPriceDim;
    InventItemSalesSetup        inventItemSalesSetup;

    _staging.selectForUpdate(true);

    _staging.ProductName = inventTable.productNameInUserLanguage(_staging.InventDimId);
    _staging.IsCatchWeightProduct = inventTable.pdsCWItem();

    if (_staging.IsCatchWeightProduct)
    {
        // EA to KG conversion factor
        unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                UnitOfMeasure::findBySymbol(#SalesUnitEA).RecId,
                UnitOfMeasure::findBySymbol(#SalesUnitKG).RecId,
                EcoResProduct::findByProductNumber(_staging.ItemId).RecId);

        _staging.Factor = decRound((unitOfMeasureConversion.Factor ? unitOfMeasureConversion.Factor : 0.00), 2);
    }

    select firstonly ExcisePerCase from siteDutySetup
        where siteDutySetup.SiteId  == _staging.InventSiteId
        &&    siteDutySetup.ItemId  == _staging.ItemId;

    _staging.ExcisePerCase = decRound(siteDutySetup.ExcisePerCase, 2);

    // Latest item price
    select firstonly itemPrice
        order by itemPrice.ActivationDate desc
        where itemPrice.ItemId == _staging.ItemId
        outer join itemPriceDim
            where itemPriceDim.inventDimId    == itemPrice.InventDimId
            &&    itemPriceDim.InventSiteId   == _staging.InventSiteId;

    if (itemPrice)
    {
        _staging.Price = decRound(itemPrice.Price, 2);
    }


    // Sales unit setup
    inventItemSalesSetup = InventItemSalesSetup::find(_staging.ItemId, _staging.InventDimId);
    // AltSalesUnit logic
    if (_staging.IsCatchWeightProduct)
    {
        _staging.AltSalesUnit = #SalesUnitKG;
    }
    else if (inventItemSalesSetup.METAltSalesUnit)
    {
        _staging.AltSalesUnit = #SalesUnitEA;
    }
    else
    {
        _staging.AltSalesUnit = #SalesUnitCS;
    }

    // CaseQty logic
    if (inventItemSalesSetup.METSalesUnit == #SalesUnitEA)
    {
        _staging.CaseQty = 1;
    }
    else
    {
        // SalesUnit to EA conversion for CaseQty
        unitOfMeasureConversion = UnitOfMeasureConversion::findByConversion(
                UnitOfMeasure::findBySymbol(inventItemSalesSetup.METSalesUnit).RecId,
                UnitOfMeasure::findBySymbol(#SalesUnitEA).RecId,
                EcoResProduct::findByProductNumber(_staging.ItemId).RecId);

        _staging.Factor = decRound((unitOfMeasureConversion.Factor ? unitOfMeasureConversion.Factor : 0.00), 2);
        _staging.CaseQty = decRound(unitOfMeasureConversion.Factor, 2);
    }
}

/// <summary>
/// Initializing the values into the data entity for the export purpose
/// </summary>
public void postLoad()
{
    str item = this.ItemId;
    changecompany(this.DataAreaId)
    {
        this.updateAdditionalData(this);
    }

    super();
}
